//! Version1 game genetics: independent saved domain, no phenotype/fitness input.
const std=@import("std");
pub const Config=struct{enabled:bool=false,law:u8=0,mutation_law:u8=0,stream_seed:u64=0,pub fn valid(c:@This())bool{return if(c.enabled)c.law==1 and c.mutation_law==1 else c.law==0 and c.mutation_law==0 and c.stream_seed==0;}};
pub fn digest(seed:u64,parent:u64,child:u64,generation:u32)[32]u8{var input=[_]u8{0}**48;@memcpy(input[0..12],"STELLA-REST1");std.mem.writeInt(u64,input[16..24],seed,.little);std.mem.writeInt(u64,input[24..32],parent,.little);std.mem.writeInt(u64,input[32..40],child,.little);std.mem.writeInt(u32,input[40..44],generation,.little);var out:[32]u8=undefined;std.crypto.hash.sha2.Sha256.hash(&input,&out,.{});return out;}
pub const Proposal=struct{delta:f32,rare:bool};
pub fn proposal(seed:u64,parent:u64,child:u64,generation:u32)Proposal{const h=digest(seed,parent,child,generation);const bits=std.mem.readInt(u64,h[0..8],.little);const rare=bits&511==0;const u=@as(f64,@floatFromInt(std.mem.readInt(u64,h[8..16],.little)>>11))/9007199254740992.0;const delta=if(rare)(if(h[16]&1==0)@as(f64,-1)else 1)*(0.1+0.2*u)else(u-0.5)*0.2;return .{.delta=@floatCast(delta),.rare=rare};}
pub fn allocation(old:f32,seed:u64,parent:u64,child:u64,generation:u32)f32{return std.math.clamp(old+proposal(seed,parent,child,generation).delta,0,1);}
test "fixed mutation vectors symmetric common and rare proposals"{var positive:usize=0;var negative:usize=0;var rare:usize=0;var rare_positive:usize=0;for(1..65537)|id|{const p=proposal(42,17,id,1);try std.testing.expectEqualDeep(p,proposal(42,17,id,1));try std.testing.expect(@abs(p.delta)<=0.3);if(p.rare){rare+=1;try std.testing.expect(@abs(p.delta)>=0.1);if(p.delta>0)rare_positive+=1;}else try std.testing.expect(@abs(p.delta)<=0.1);if(p.delta>0)positive+=1 else if(p.delta<0)negative+=1;const v=allocation(0,42,17,id,1);try std.testing.expect(v>=0 and v<=0.3);}
 try std.testing.expect(positive>31000 and negative>31000 and rare>60 and rare<220 and rare_positive>20);std.debug.print("PROTECT_MUTATION proposals65536 positive{} negative{} rare{} rarepositive{}\n",.{positive,negative,rare,rare_positive});const h=digest(42,17,1,1);std.debug.print("PROTECT_VECTOR {s}\n",.{std.fmt.fmtSliceHexLower(&h)});
}
